do $$ begin if exists(select 1 from cron.job where jobname='djm-clubelo-team-strength-daily') then perform cron.unschedule('djm-clubelo-team-strength-daily'); end if; end$$;
select cron.schedule('djm-clubelo-team-strength-daily','11 5 * * *',$$select net.http_post(url := 'https://xogoigaaskmuspiehkba.supabase.co/functions/v1/refresh-clubelo-team-strength',headers := jsonb_build_object('Content-Type','application/json','x-djm-cron',(select decrypted_secret from vault.decrypted_secrets where name='djm_push_cron_secret' limit 1)),body := jsonb_build_object('source','clubelo_daily'),timeout_milliseconds := 60000);$$);